function bulkFileReport(){let batch=requireBulk();return batch.files.map(f=>{let selected=[],skipped=[],pending=[],saved=[];for(let part of f.parts){let b=batch.buckets.get(part.key);if(f.excluded)skipped.push(b.date);else if(!b.choice)pending.push(b.date);else if(b.choice===part.id&&(!b.chosenFile||b.chosenFile===f.id)){(b.choice==='saved'?saved:selected).push(b.date);}else skipped.push(b.date);}let status=f.status==='invalid'?'Invalid file':f.excluded?'Skipped by you':f.manualOverride?(pending.length?'Override needs review':skipped.length?'Override partly selected':'Override selected'):f.status==='duplicate'?(saved.length?'Already saved · verified':selected.length?'Duplicate copy · ready via another file':'Duplicate copy'):pending.length?'Needs overlap choice':selected.length?(skipped.length?'Partly selected':'Selected or already saved'):saved.length?'Already saved · verified':'Not selected';return {id:f.id,file:f.file,status,sourceStatus:f.status,canOverride:f.status!=='invalid',excluded:f.excluded,manualOverride:f.manualOverride,stream:f.stream,rows:f.rows,dates:[...new Set(f.parts.map(p=>batch.buckets.get(p.key).date))].sort(),selectedDates:[...new Set([...selected,...saved])].sort(),savedDates:[...new Set(saved)].sort(),skippedDates:[...new Set(skipped)].sort(),pendingDates:[...new Set(pending)].sort(),note:f.note||'',hash:f.hash};});}

function chooseBulk(p){let batch=requireBulk(),b=batch.buckets.get(p.key);if(!b)throw Error('Reporting date not found in this preview.');if(p.choice!==null&&p.choice!=='skip'&&!b.candidates.some(c=>c.id===p.choice))throw Error('Report version not found.');b.choice=p.choice;b.chosenFile=null;b.manualDateChoice=true;b.reason=p.choice==='skip'?'Excluded explicitly by user':'Version selected by user';batch.pending=null;return bulkPreview();}
function applyBulkPolicy(mode){let batch=requireBulk(),resolved=0;for(let b of batch.buckets.values()){if(b.choice)continue;if(mode==='skip'){b.choice='skip';b.reason='Unresolved date excluded explicitly';resolved++;continue;}if(mode!=='latest')throw Error('Unknown overlap policy.');let options=b.candidates.filter(c=>b.incoming.has(c.id)).map(c=>{let stamps=c.files.map(id=>batch.files.find(f=>f.id===id)).filter(f=>f&&!f.excluded).map(f=>f.exportedAt).filter(Number.isFinite);return {id:c.id,time:stamps.length?Math.max(...stamps,Number.isFinite(c.exportedAt)?c.exportedAt:0):(c.exportedAt??null)};});if(options.some(o=>o.time===null))continue;options.sort((a,b)=>b.time-a.time);if(options.length>1&&options[0].time===options[1].time)continue;b.choice=options[0].id;b.reason='Latest unambiguous CreatedOn filename timestamp';resolved++;}batch.pending=null;return {...bulkPreview(),policyResolved:resolved};}
function commitBulk(partitioned=false){let batch=requireBulk();if(batch.pending&&!partitioned)return Packed.plain(batch.pending);let unresolved=[...batch.buckets.values()].filter(b=>!b.choice);if(unresolved.length)throw Error('Resolve or explicitly skip '+unresolved.length+' overlapping date(s) before importing.');let replacements=new Map(),parts=[];for(let b of batch.buckets.values()){let c=selectedCandidate(b);if(c&&!c.saved){replacements.set(b.key,c);parts.push({store:c.rows.store,rows:c.rows});}}let keep=[],count=0;for(let [key,ids]of workerData.store.partitions)if(!replacements.has(key)){keep.push(ids);count+=ids.length;}let ids=new Uint32Array(count),offset=0;for(let arr of keep){ids.set(arr,offset);offset+=arr.length;}if(count)parts.unshift({store:workerData.store,rows:new Packed.Rows(workerData.store,ids)});let imports=[],processedHashes=new Set(),known=new Set(workerData.imports.map(x=>x.hash).filter(Boolean));for(let f of batch.files){if(f.excluded||f.status==='invalid')continue;let accepted=f.parts.filter(part=>{let b=batch.buckets.get(part.key);return b.choice===part.id&&(!b.chosenFile||b.chosenFile===f.id);});if(!accepted.length)continue;let complete=accepted.length===f.parts.length;if(complete&&processedHashes.has(f.hash))continue;if(complete&&known.has(f.hash)&&!f.manualOverride&&accepted.every(p=>p.id==='saved'))continue;let dates=[...new Set(accepted.map(p=>p.key.slice(p.key.indexOf('|')+1)))].sort(),record={file:f.file,stream:f.stream,hash:complete?f.hash:undefined,sourceHash:f.hash,dates,originalDates:[...new Set(f.parts.map(p=>p.key.slice(p.key.indexOf('|')+1)))].sort(),rows:accepted.reduce((n,p)=>n+batch.buckets.get(p.key).candidates.find(c=>c.id===p.id).rows.length,0),originalRows:f.rows,partial:!complete,forced:!!f.manualOverride,at:new Date().toISOString()};imports.push(record);if(complete){known.add(f.hash);processedHashes.add(f.hash);}}if(!replacements.size&&!imports.length)throw Error('Nothing new to save. All selected reports are already saved or excluded.');if(partitioned)return {imports,partitions:[...replacements].map(([key,c])=>({key,store:c.rows.store,rows:c.rows}))};let store=replacements.size?Packed.combine(parts):workerData.store;batch.pending={version:2,targets:workerData.targets||[],targetImports:workerData.targetImports||[],store,rows:store.all(),imports:[...workerData.imports,...imports],updatedAt:new Date().toISOString()};return Packed.plain(batch.pending);}
async function salesRunWorkerTask(type,p={}){if(type==='bulkStart')return startBulk();if(type==='bulkFile')return addBulkFile(p);if(type==='bulkPreview')return bulkPreview();if(type==='bulkFileAction')return chooseBulkFile(p);if(type==='bulkChoose')return chooseBulk(p);if(type==='bulkPolicy')return applyBulkPolicy(p.mode);if(type==='bulkReport')return bulkFileReport();if(type==='bulkDiscard'){bulkImport=null;return {ok:true};}if(type==='bulkCommit')return commitBulk();if(type==='bulkCommitPartitions')return commitBulk(true);if(type==='bulkAccept'){let batch=requireBulk();if(!batch.pending)throw Error('No prepared bulk import.');workerData=batch.pending;bulkImport=null;draftParts=[];draftImports=[];pendingData=null;selectionCache.clear();return {ok:true};}if(type==='load')bulkImport=null;return consoleRunWorkerTask(type,p);}

// Target registry shared by the browser and background worker.
var TargetEngine=(()=>{
const scopes={kam:{label:'KAM',column:'KAM',field:'kam'},seller:{label:'Seller',column:'Seller',field:'seller'},category:{label:'Category',column:'Category',field:'cat1'},vertical:{label:'Vertical',column:'Vertical',field:'business'}};
const metrics=['gmv','gos','nmv','nos'];
const col={gmv:'GMVTarget',gos:'GOSTarget',nmv:'NMVTarget',nos:'NOSTarget'};
const key=r=>JSON.stringify([r.scope,r.cadence,r.period,r.level||'',r.entity]);
const equal=(a,b)=>metrics.every(k=>a[k]===b[k]);
function parse(text,scope,cadence,file){if(!scopes[scope]||!['daily','monthly'].includes(cadence))throw Error('Select a target level and frequency.');let rows=Engine.parseCSV(text),dateCol=cadence==='daily'?'Date':'Month',entityCol=scopes[scope].column,required=[dateCol,entityCol,...(scope==='category'?['CategoryLevel']:[])];for(let c of required)if(!(c in rows[0]))throw Error('Missing column '+c+'. Download the matching template.');if(!metrics.some(k=>col[k] in rows[0]))throw Error('At least one target metric column is required.');return rows.map((r,i)=>{let period=(r[dateCol]||'').trim(),entity=(r[entityCol]||'').trim(),level=scope==='category'?(r.CategoryLevel||'').trim():'';if(!entity)throw Error('Row '+(i+2)+': '+entityCol+' is required.');if(cadence==='daily'){if(!/^\d{4}-\d{2}-\d{2}$/.test(period)||Engine.dateISO(period).slice(0,10)!==period)throw Error('Row '+(i+2)+': Date must be YYYY-MM-DD.');}else if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(period))throw Error('Row '+(i+2)+': Month must be YYYY-MM.');if(scope==='category'&&!/^[1-5]$/.test(level))throw Error('Row '+(i+2)+': CategoryLevel must be 1 to 5.');let x={scope,cadence,period,entity,level,file};for(let k of metrics){let v=(r[col[k]]||'').trim();x[k]=v===''?null:Number(v.replace(/,/g,''));if(x[k]!==null&&(!Number.isFinite(x[k])||x[k]<0||(['gos','nos'].includes(k)&&!Number.isInteger(x[k]))))throw Error('Row '+(i+2)+': '+col[k]+' must be non-negative'+(['gos','nos'].includes(k)?' and a whole number.':'.'));}if(metrics.every(k=>x[k]===null))throw Error('Row '+(i+2)+': enter at least one target.');return x;});}
function merge(existing,incoming){let map=new Map(existing.map(r=>[key(r),r])),seen=new Map(),added=0,replaced=0,duplicates=0;for(let r of incoming){let k=key(r);if(seen.has(k)){if(!equal(seen.get(k),r))throw Error('Conflicting targets in selected files for '+r.entity+' · '+r.period+'. Keep one version before uploading.');duplicates++;continue;}seen.set(k,r);if(map.has(k)){if(equal(map.get(k),r)){duplicates++;continue;}replaced++;}else added++;map.set(k,r);}return {rows:[...map.values()],added,replaced,duplicates};}
function templates(scope,cadence){let s=scopes[scope],heads=[cadence==='daily'?'Date':'Month',s.column,...(scope==='category'?['CategoryLevel']:[]),...metrics.map(k=>col[k])];return heads.join(',')+'\r\n';}
const signed=v=>v==null?'—':(v>0?'+':v<0?'−':'')+(Math.abs(v)*100).toFixed(1)+'%';
const band=v=>v==null?'neutral':v>=1?'achieved':v>=.8&&v<=.9?'watch':v>.9?'near':'behind';
return {scopes,metrics,col,key,equal,parse,merge,templates,signed,band};
})();

let targetDraft=null;
async function runWorkerTask(type,p={}){
 if(type==='targetReport'){
  let scope=p.scope,cadence=p.cadence,metric=p.metric,level=scope==='category'?String(p.level||1):'',field=scope==='category'?'cat'+level:TargetEngine.scopes[scope].field;
  let start=cadence==='monthly'?p.from.slice(0,7)+'-01':p.from,end=p.to,days=Engine.dateRange(start,end),periods=[...new Set(days.map(d=>cadence==='monthly'?d.slice(0,7):d))],registry=(workerData.targets||[]).filter(r=>r.scope===scope&&r.cadence===cadence&&r.level===level&&periods.includes(r.period)),targets=new Map();
  for(let r of registry){if(!targets.has(r.entity))targets.set(r.entity,[]);targets.get(r.entity).push(r);}
  let rows=selection(start,end,{}),groups=Engine.groupLite(rows,[field]),actual=new Map(groups.map(g=>[g.labels[0],g])),stream=['nmv','nos'].includes(metric)?'net':'gross',have=days.filter(d=>workerData.store.coverage[stream].has(d)).length;
  let names=new Set([...targets.keys(),...actual.keys()]),result=[...names].map(entity=>{let rs=targets.get(entity)||[],measured=rs.filter(r=>r[metric]!==null),complete=measured.length===periods.length,target=measured.length?measured.reduce((n,r)=>n+r[metric],0):null,g=actual.get(entity),value=have?(g?.[metric]||0):null,attainment=complete&&target>0&&have===days.length?value/target:null;return {entity,target,actual:value,attainment,gap:complete&&value!==null?value-target:null,targetHave:measured.length,targetTotal:periods.length,matched:!!g,status:!measured.length?'No target':!complete?'Partial target dates':have!==days.length?'Missing sales dates':target===0?'Zero target':!g?'No matching sales':'Complete'};});
  return {rows:result,start,end,have,total:days.length,periods:periods.length,targetRows:registry.length,scope,cadence,metric};
 }
 if(type==='targetStart'){targetDraft={base:workerData,rows:[],files:[],errors:[],pending:null};return {ok:true};}
 if(type==='targetFile'){if(!targetDraft||targetDraft.base!==workerData)throw Error('Start a new target preview.');try{let rows=TargetEngine.parse(await p.file.text(),p.scope,p.cadence,p.file.name);targetDraft.rows.push(...rows);targetDraft.files.push({file:p.file.name,scope:p.scope,cadence:p.cadence,rows:rows.length});return {ok:true,rows:rows.length};}catch(e){targetDraft.errors.push({file:p.file.name,error:e.message});return {ok:false,error:e.message};}}
 if(type==='targetPreview'){if(!targetDraft)throw Error('No target preview.');let merged=null,conflict='';try{merged=TargetEngine.merge(workerData.targets||[],targetDraft.rows);}catch(e){conflict=e.message;}return {files:targetDraft.files,errors:targetDraft.errors,conflict,rows:targetDraft.rows.slice(0,50),total:targetDraft.rows.length,added:merged?.added||0,replaced:merged?.replaced||0,duplicates:merged?.duplicates||0};}
 if(type==='targetDiscard'){targetDraft=null;return {ok:true};}
 if(type==='targetCommit'){if(!targetDraft||targetDraft.base!==workerData)throw Error('History changed. Upload target files again.');let merged=TargetEngine.merge(workerData.targets||[],targetDraft.rows);if(!merged.added&&!merged.replaced)throw Error('No new or changed targets.');targetDraft.pending={...workerData,targets:merged.rows,targetImports:[...(workerData.targetImports||[]),...targetDraft.files.map(f=>({...f,at:new Date().toISOString()}))],updatedAt:new Date().toISOString()};return Packed.plain(targetDraft.pending);}
 if(type==='targetAccept'){if(!targetDraft?.pending)throw Error('No pending target save.');workerData=targetDraft.pending;targetDraft=null;selectionCache.clear();return {ok:true};}
 if(type==='bulkStart'||type==='load'){targetDraft=null;}
 return salesRunWorkerTask(type,p);
}
